script.inlineScript:
/**
  * @param {params} params
  * @param {api} params.api
  * @param {TransformApiHelpers} params.helpers
  */
function evaluateProperty({api, helpers}) {
	return helpers.translateSync('These groups have relevant roles that can use this product. Choose the groups you want to allocate subscriptions to.');
}

/**
  * @param {params} params
  * @param {api} params.api
  * @param {TransformApiHelpers} params.helpers
  */
function evaluateProperty({api, helpers}) {
	return helpers.translateSync('Product');
}

/**
 * @param {params} params
 * @param {api} params.api
 * @param {TransformApiHelpers} params.helpers
 */
function evaluateProperty({
    api,
    helpers
}) {
    const availableCount = api.data.sub_ent_record.result.purchased_count.displayValue;
    const allocatingCount = api.state.relevantUsersAllocatedCount;
    return helpers.translateSync('You have {0} subscriptions, but allocating {1} subscriptions would exceed the number of subscriptions purchased. You can still allocate now and review subscriptions allocated at renewal time.', availableCount, allocatingCount);
}

/**
  * @param {params} params
  * @param {api} params.api
  * @param {TransformApiHelpers} params.helpers
  */
function evaluateProperty({api, helpers}) {
	return helpers.translateSync('Filter groups');
}

/**
* @param {params} params
* @param {api} params.api
* @param {any} params.event
*/
function evaluateEvent({api, event}) {
	return {
		event: 'Add groups from all groups view',
		value: {onClick: true}
	};
}
